import{_ as a,o,c as t,a5 as n}from"./chunks/framework.DSg0KOwT.js";const h=JSON.parse('{"title":"Apache Gluten","titleTemplate":":title | Spark Tuning Reference","description":"Apache Gluten (Velox backend): plugin and off-heap memory settings, columnar shuffle and join switches, fallback cases and how to read them in the plan, plus Gluten-based Fabric and Google Cloud native engines.","frontmatter":{"title":"Apache Gluten","titleTemplate":":title | Spark Tuning Reference","description":"Apache Gluten (Velox backend): plugin and off-heap memory settings, columnar shuffle and join switches, fallback cases and how to read them in the plan, plus Gluten-based Fabric and Google Cloud native engines."},"headers":[],"relativePath":"tuning-reference/native-gluten.md","filePath":"tuning-reference/native-gluten.md"}'),s={name:"tuning-reference/native-gluten.md"};function r(i,e,l,f,c,d){return o(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="native-gluten" tabindex="-1">Apache Gluten <a class="header-anchor" href="#native-gluten" aria-label="Permalink to &quot;Apache Gluten {#native-gluten}&quot;">​</a></h1><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><p>Gluten is a middle layer that offloads the execution of JVM-based SQL engines to native engines<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup>. This page covers its Velox backend. Spark keeps the control flow: Gluten transforms Spark&#39;s whole-stage physical plan into a Substrait plan, sends it to the native engine, and reuses Spark&#39;s distributed control flow<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1:1]</a></sup>. The notes here follow Gluten&#39;s documentation on its main branch, which is not versioned, so check them against the release you run.</p><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><p>The Velox backend needs four static settings: <code>spark.plugins</code> set to <code>org.apache.gluten.GlutenPlugin</code>, <code>spark.shuffle.manager</code> set to <code>org.apache.spark.shuffle.sort.ColumnarShuffleManager</code>, <code>spark.memory.offHeap.enabled</code> set to <code>true</code>, and a <code>spark.memory.offHeap.size</code><sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup>. Static means they are fixed when the application starts.</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.plugins</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=org.apache.gluten.GlutenPlugin</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.shuffle.manager</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=org.apache.spark.shuffle.sort.ColumnarShuffleManager</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.memory.offHeap.enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">spark.memory.offHeap.size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=20g</span></span></code></pre></div><p>The officially supported Spark versions are 3.4.4, 3.5.5, 4.0.2 and 4.1.1, and Spark 4.0 and 4.1 require JDK 17 or later and Scala 2.13<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup>. On an unofficially supported Spark version, <code>NoSuchMethodError</code> can be thrown at runtime<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup>.</p><h2 id="memory" tabindex="-1">Memory <a class="header-anchor" href="#memory" aria-label="Permalink to &quot;Memory&quot;">​</a></h2><p>Gluten allocates native memory from <code>spark.memory.offHeap.size</code> even when off-heap memory is otherwise disabled, and its configuration reference recommends a larger value if the plugin runs out of memory<sup class="footnote-ref"><a href="#fn2" id="fnref2:1">[2:1]</a></sup>. The Velox example in its getting-started guide uses <code>--executor-memory 25g</code>, <code>spark.memory.offHeap.size=20g</code> and <code>spark.executor.memoryOverhead=5g</code>, and says to adjust executor cores, memory and off-heap size to your environment<sup class="footnote-ref"><a href="#fn3" id="fnref3:1">[3:1]</a></sup>. Two further settings shape how that memory is shared:</p><ul><li><code>spark.gluten.memory.isolation</code> (default <code>false</code>) caps the off-heap memory each task can use at executor memory divided by the maximum task slots. It is recommended when Gluten serves concurrent queries in one session, because not all memory Gluten allocates is guaranteed to be spillable<sup class="footnote-ref"><a href="#fn2" id="fnref2:2">[2:2]</a></sup>.</li><li><code>spark.gluten.memory.overAcquiredMemoryRatio</code> (default <code>0.3</code>) lets the Velox backend over-acquire that ratio of the allocated memory as a backup against out-of-memory errors<sup class="footnote-ref"><a href="#fn2" id="fnref2:3">[2:3]</a></sup>.</li></ul><p>The Velox backend supports spill-to-disk, and <code>spillStrategy</code> set to <code>auto</code> (the default) lets the Spark memory manager manage Velox&#39;s spilling, while <code>none</code> disables it<sup class="footnote-ref"><a href="#fn3" id="fnref3:2">[3:2]</a></sup>. Gluten&#39;s documentation warns that <code>OutOfMemoryException</code> can still occur with spill-to-disk when the shuffle partition count is large, and advises reducing it<sup class="footnote-ref"><a href="#fn4" id="fnref4:1">[4:1]</a></sup>. See <a href="./memory-model.html">Memory Management</a> and <a href="./bottleneck-spill.html">spill</a> for the Spark side. The experimental <code>spark.gluten.velox.offHeapBroadcastBuildRelation.enabled</code> (default <code>false</code>) stores broadcast build relations off-heap instead of on-heap<sup class="footnote-ref"><a href="#fn3" id="fnref3:3">[3:3]</a></sup>.</p><h2 id="joins-and-shuffle" tabindex="-1">Joins and shuffle <a class="header-anchor" href="#joins-and-shuffle" aria-label="Permalink to &quot;Joins and shuffle&quot;">​</a></h2><p>The columnar shuffle is on by default (<code>spark.gluten.sql.columnar.shuffle</code>, <code>true</code>) and its codec, set with <code>spark.gluten.sql.columnar.shuffle.codec</code>, supports lz4 and zstd<sup class="footnote-ref"><a href="#fn2" id="fnref2:4">[2:4]</a></sup>. For joins, <code>spark.gluten.sql.columnar.forceShuffledHashJoin</code> defaults to <code>true</code>, and separate switches control the columnar sort-merge join (<code>spark.gluten.sql.columnar.sortMergeJoin</code>, which &quot;should be set with preferSortMergeJoin=false&quot;), the broadcast join and the broadcast exchange<sup class="footnote-ref"><a href="#fn2" id="fnref2:5">[2:5]</a></sup>. The strategy-selection rules on the <a href="./joins.html">Join Optimization</a> page describe vanilla Spark&#39;s choices, so verify the physical plan of a Gluten job rather than assuming them.</p><h2 id="fallback" tabindex="-1">Fallback <a class="header-anchor" href="#fallback" aria-label="Permalink to &quot;Fallback&quot;">​</a></h2><p>Gluten falls back to vanilla Spark in several documented cases:</p><ul><li>ANSI mode: &quot;If ANSI is enabled, Spark plan&#39;s execution will always fall back to vanilla Spark.&quot;<sup class="footnote-ref"><a href="#fn4" id="fnref4:2">[4:2]</a></sup></li><li>File formats: Gluten fully supports Parquet and partially supports ORC, and the scan falls back for other formats<sup class="footnote-ref"><a href="#fn4" id="fnref4:3">[4:3]</a></sup>.</li><li>Partitioned table scans need the partition information in the file path, and without it the scan falls back<sup class="footnote-ref"><a href="#fn4" id="fnref4:4">[4:4]</a></sup>.</li><li>Bucket writes are not supported and fall back<sup class="footnote-ref"><a href="#fn4" id="fnref4:5">[4:5]</a></sup>.</li><li>Parquet scans of the Byte type fall back<sup class="footnote-ref"><a href="#fn4" id="fnref4:6">[4:6]</a></sup>.</li></ul><p>Two settings tune fallback. <code>spark.gluten.sql.columnar.query.fallback.threshold</code> (default <code>-1</code>) is the threshold for whether a query falls back, counted from the number of <code>ColumnarToRow</code> and vanilla leaf nodes. <code>spark.gluten.sql.columnar.fallback.expressions.threshold</code> (default <code>50</code>) falls back a filter or project when the number of nested expressions reaches it, because Spark codegen can be faster in that case<sup class="footnote-ref"><a href="#fn2" id="fnref2:6">[2:6]</a></sup>.</p><h2 id="seeing-where-it-ran" tabindex="-1">Seeing where it ran <a class="header-anchor" href="#seeing-where-it-ran" aria-label="Permalink to &quot;Seeing where it ran&quot;">​</a></h2><p>To see what can be offloaded and why a part fell back, the getting-started guide says to disable AQE (<code>spark.sql.adaptive.enabled=false</code>) so that plan validation runs in Gluten, then read the physical plan with <code>explain()</code><sup class="footnote-ref"><a href="#fn3" id="fnref3:4">[3:4]</a></sup>. In that plan, the symbol <code>^</code> marks a plan offloaded to Velox in a stage, and <code>VeloxColumnarToRowExec</code> or <code>GlutenRowToArrowColumnar</code> indicates a fallback operator before or after it<sup class="footnote-ref"><a href="#fn3" id="fnref3:5">[3:5]</a></sup>. A helper, <code>df.fallbackSummary</code> from <code>org.apache.spark.sql.execution.GlutenImplicits</code>, returns the fallback summary of a Dataset<sup class="footnote-ref"><a href="#fn3" id="fnref3:6">[3:6]</a></sup>.</p><h2 id="known-incompatibilities" tabindex="-1">Known incompatibilities <a class="header-anchor" href="#known-incompatibilities" aria-label="Permalink to &quot;Known incompatibilities&quot;">​</a></h2><p>Gluten supports only Spark&#39;s default case-insensitive mode, and enabling case-sensitive mode can give incorrect results. Velox does not support NaN, so comparisons involving NaN can give unexpected results, and it handles only double-quoted strings in JSON data. Gluten ignores <code>spark.sql.parquet.datetimeRebaseModeInRead</code>, and &quot;not all parquet configurations are honored&quot;<sup class="footnote-ref"><a href="#fn4" id="fnref4:7">[4:7]</a></sup>.</p><h2 id="engines-built-on-gluten" tabindex="-1">Engines built on Gluten <a class="header-anchor" href="#engines-built-on-gluten" aria-label="Permalink to &quot;Engines built on Gluten&quot;">​</a></h2><p><strong>Microsoft Fabric native execution engine.</strong> Fabric&#39;s engine is based on two open-source components, Velox and Apache Gluten. Supported operators are offloaded from the JVM to a vectorized C++ execution path, and Fabric keeps its Spark query optimizations, including AQE<sup class="footnote-ref"><a href="#fn5" id="fnref5">[5]</a></sup>. When a query can&#39;t run natively the operation falls back to the traditional Spark engine automatically, and plan nodes with a <code>Transformer</code> suffix, <code>*NativeFileScan</code> or <code>VeloxColumnarToRowExec</code> show native execution<sup class="footnote-ref"><a href="#fn5" id="fnref5:1">[5:1]</a></sup>. It is enabled through the environment&#39;s acceleration setting or <code>spark.native.enabled</code>, it doesn&#39;t support structured streaming, doesn&#39;t accelerate queries against JSON and XML, and on Runtime 1.3 falls back to vanilla Spark when ANSI SQL mode is on<sup class="footnote-ref"><a href="#fn5" id="fnref5:2">[5:2]</a></sup>. Fabric describes it as suited to computationally intensive queries rather than simple or I/O-bound ones<sup class="footnote-ref"><a href="#fn5" id="fnref5:3">[5:3]</a></sup>.</p><p><strong>Google Cloud native query execution.</strong> Google&#39;s native query execution is a native engine based on Apache Gluten and Velox that runs parts of a Spark query outside the JVM. It is enabled by setting <code>spark.dataproc.lightningEngine.runtime</code> to <code>native</code><sup class="footnote-ref"><a href="#fn6" id="fnref6">[6]</a></sup><sup class="footnote-ref"><a href="#fn7" id="fnref7">[7]</a></sup>. It falls back to standard Spark when ANSI mode is enabled, when case-sensitive mode is enabled, or when partitioned table scans lack partition information in the path<sup class="footnote-ref"><a href="#fn6" id="fnref6:1">[6:1]</a></sup>.</p><h2 id="confidence" tabindex="-1">Confidence <a class="header-anchor" href="#confidence" aria-label="Permalink to &quot;Confidence&quot;">​</a></h2><p>The settings, defaults and fallback cases above are taken from Gluten&#39;s own configuration reference, getting-started guide and limitations page on its main branch, and from the Fabric and Google Cloud documentation for the managed engines. Defaults in the configuration reference can change between Gluten releases, so confirm a setting against the release you run. The plan-reading guidance is documented for the Velox backend only.</p><h2 id="limitations-false-positive-risk" tabindex="-1">Limitations / false-positive risk <a class="header-anchor" href="#limitations-false-positive-risk" aria-label="Permalink to &quot;Limitations / false-positive risk&quot;">​</a></h2><p>Fallback is per operator: a mostly native plan can still contain fallback operators, each marked by a transition operator in the plan<sup class="footnote-ref"><a href="#fn3" id="fnref3:7">[3:7]</a></sup>. Diagnosing fallbacks means disabling AQE<sup class="footnote-ref"><a href="#fn3" id="fnref3:8">[3:8]</a></sup>, so the plan you inspect is a diagnostic view, not the AQE-enabled plan your production runs use (see <a href="./aqe.html">Adaptive Query Execution</a>). Fabric and Google Cloud document their own limits separately, and those differ from Gluten&#39;s.</p><h2 id="sources" tabindex="-1">Sources <a class="header-anchor" href="#sources" aria-label="Permalink to &quot;Sources&quot;">​</a></h2><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/gluten/main/docs/index.md" target="_blank" rel="noreferrer">Apache Gluten documentation</a> <a href="#fnref1" class="footnote-backref">↩︎</a> <a href="#fnref1:1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/gluten/main/docs/Configuration.md" target="_blank" rel="noreferrer">Apache Gluten configuration</a> <a href="#fnref2" class="footnote-backref">↩︎</a> <a href="#fnref2:1" class="footnote-backref">↩︎</a> <a href="#fnref2:2" class="footnote-backref">↩︎</a> <a href="#fnref2:3" class="footnote-backref">↩︎</a> <a href="#fnref2:4" class="footnote-backref">↩︎</a> <a href="#fnref2:5" class="footnote-backref">↩︎</a> <a href="#fnref2:6" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/gluten/main/docs/get-started/Velox.md" target="_blank" rel="noreferrer">Apache Gluten: Velox backend getting started</a> <a href="#fnref3" class="footnote-backref">↩︎</a> <a href="#fnref3:1" class="footnote-backref">↩︎</a> <a href="#fnref3:2" class="footnote-backref">↩︎</a> <a href="#fnref3:3" class="footnote-backref">↩︎</a> <a href="#fnref3:4" class="footnote-backref">↩︎</a> <a href="#fnref3:5" class="footnote-backref">↩︎</a> <a href="#fnref3:6" class="footnote-backref">↩︎</a> <a href="#fnref3:7" class="footnote-backref">↩︎</a> <a href="#fnref3:8" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p><a href="https://raw.githubusercontent.com/apache/gluten/main/docs/velox-backend-limitations.md" target="_blank" rel="noreferrer">Apache Gluten: Velox backend limitations</a> <a href="#fnref4" class="footnote-backref">↩︎</a> <a href="#fnref4:1" class="footnote-backref">↩︎</a> <a href="#fnref4:2" class="footnote-backref">↩︎</a> <a href="#fnref4:3" class="footnote-backref">↩︎</a> <a href="#fnref4:4" class="footnote-backref">↩︎</a> <a href="#fnref4:5" class="footnote-backref">↩︎</a> <a href="#fnref4:6" class="footnote-backref">↩︎</a> <a href="#fnref4:7" class="footnote-backref">↩︎</a></p></li><li id="fn5" class="footnote-item"><p><a href="https://learn.microsoft.com/en-us/fabric/data-engineering/native-execution-engine-overview" target="_blank" rel="noreferrer">Native execution engine for Fabric Data Engineering</a> <a href="#fnref5" class="footnote-backref">↩︎</a> <a href="#fnref5:1" class="footnote-backref">↩︎</a> <a href="#fnref5:2" class="footnote-backref">↩︎</a> <a href="#fnref5:3" class="footnote-backref">↩︎</a></p></li><li id="fn6" class="footnote-item"><p><a href="https://docs.cloud.google.com/dataproc-serverless/docs/guides/native-query-execution" target="_blank" rel="noreferrer">Native query execution (Google Cloud managed Spark service)</a> <a href="#fnref6" class="footnote-backref">↩︎</a> <a href="#fnref6:1" class="footnote-backref">↩︎</a></p></li><li id="fn7" class="footnote-item"><p><a href="https://docs.cloud.google.com/dataproc-serverless/docs/concepts/properties" target="_blank" rel="noreferrer">Spark properties (Google Cloud managed Spark service)</a> <a href="#fnref7" class="footnote-backref">↩︎</a></p></li></ol></section>`,31)])])}const p=a(s,[["render",r]]);export{h as __pageData,p as default};
